import json
h=w=20
g=[[0]*w for _ in range(h)]
# Original solid 2 field
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
# Sparse 1 markers
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers: g[r][c]=1
# Extend each source row toward the edge(s) not blocked by a marker on that row.
row_markers={r:c for r,c in markers if 2<=r<=8}
for r in range(2,9):
    if r not in row_markers:
        for c in range(w):
            if g[r][c]!=1: g[r][c]=2
    elif row_markers[r]<9: # marker is left of source; extend right
        for c in range(9,w):
            if g[r][c]!=1: g[r][c]=2
    else: # marker is right of source; extend left
        for c in range(0,16):
            if g[r][c]!=1: g[r][c]=2
# Extend each source column upward; continue downward only if no marker is below it.
blocked_cols={c for r,c in markers if r>8 and 9<=c<=15}
for c in range(9,16):
    for r in range(0,2):
        if g[r][c]!=1: g[r][c]=2
    if c not in blocked_cols:
        for r in range(9,h):
            if g[r][c]!=1: g[r][c]=2
assert len(g)==20 and all(len(row)==20 for row in g)
assert set(sum(g,[])) <= {0,1,2}
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
